      {{ partial "docs/nav.html" (dict "drawer" false "here" .RelPermalink "version" $version "isArchived" $isArchived) }}
    </div>

    <div class="dashboard-panel main">
      {{ partial "hero.html" . }}
      {{ partial "content.html" . }}
      {{ partial "docs/pagination.html" . }}
      {{ partial "footer.html" . }}
    </div>
    {{ end }}
  </div>

  {{ partial "docs/drawer.html" . }}
</div>

{{ $version := index (split .File.Path "/") 1 }}
<div class="drawer" :class="{ 'is-visible': drawer }">
  {{ partial "docs/nav.html" (dict "drawer" true "here" .RelPermalink "version" $version) }}
</div>

{{ $sections    := where site.Sections "Section" "docs" }}
{{ $here        := .here }}
{{ $docsVersion := .version }}

{{ $versionParseIndex := 1 }}
{{ $archivedSections  := slice (site.GetPage "/docs/archives") }}
