import mod = require("mod");
console.log(mod);

export = {
    p1: true,
    p2: false
};
```

```js
// @Filename: main.js
"use strict";
const mod = require("mod");
console.log(mod);

module.exports = {
    p1: true,
    p2: false
};
```

### `system`

#### Summary

- Designed for use with the [SystemJS module loader](https://github.com/systemjs/systemjs).

#### Examples

```ts
